 62	
 63	    expect(violations).toEqual([]);
 64	  });
 65	
 66	  it('every RegExp route uses only named capture groups — no positional (unnamed) groups', () => {
 67	    /**
 68	     * A positional (unnamed) capture group is an opening parenthesis `(` that is
 69	     * NOT followed by either:
 70	     *   - `?:` — non-capturing group
 71	     *   - `?<` — named capture group
 72	     *   - `?=` — positive lookahead
 73	     *   - `?!` — negative lookahead
 74	     *   - `?<=` — positive lookbehind
 75	     *   - `?<!` — negative lookbehind
 76	     *
 77	     * The regex below detects any `(` that does NOT start one of the above
 78	     * special-group syntaxes (i.e., it is a plain capturing group).
 79	     */
 80	    const POSITIONAL_GROUP_RE = /\((?!\?)/;
 81	
 82	    const violations = routes.filter((route) => {
 83	      if (typeof route.path !== 'object') return false;   // skip string routes
 84	      return POSITIONAL_GROUP_RE.test(route.path.source);
 85	    });
 86	
 87	    const violatingPatterns = violations.map((r) => ({
 88	      method: r.method,
 89	      source: (r.path as RegExp).source,
 90	    }));
 91	
 92	    expect(violatingPatterns).toEqual([]);
 93	  });
 94	
 95	  it('no two routes share the same method + path combination', () => {
 96	    const seen = new Map<string, number>();   // key → first index
 97	    const duplicates: Array<{ index: number; method: string; path: string }> = [];
 98	
 99	    routes.forEach((route, idx) => {
100	      const key = `${route.method} ${pathKey(route.path)}`;

101	      if (seen.has(key)) {
102	        duplicates.push({ index: idx, method: route.method, path: pathKey(route.path) });
103	      } else {
104	        seen.set(key, idx);
105	      }
106	    });
107	
108	    expect(duplicates).toEqual([]);
109	  });
110	
111	});

